<?php
declare(strict_types=1);
/** Attendance recovery and refund bookkeeping. These functions never transfer money. */
function lifecycleStaff(array $u):void{requirev(in_array($u['role'],['owner','organizer'],true),'幹事の権限が必要です。');}
function billedRegistration(array $p):int{return in_array($p['status'],['cancelled','rejoin_requested'],true)?0:(int)$p['amount'];}
function refundedRegistration(int $id):int{return (int)one("SELECT COALESCE(SUM(amount),0) n FROM refunds WHERE registration_id=? AND status='recorded'",[$id])['n'];}
function plannedRegistrationRefund(int $id):int{return (int)one("SELECT COALESCE(SUM(amount),0) n FROM refunds WHERE registration_id=? AND status='planned'",[$id])['n'];}
function netPaidRegistration(int $id):int{return paidRegistration($id)-refundedRegistration($id);}
function availableRegistrationRefund(int $id):int{$p=one('SELECT * FROM registrations WHERE id=?',[$id]);requirev((bool)$p,'申込がありません。');return max(0,netPaidRegistration($id)-billedRegistration($p)-plannedRegistrationRefund($id));}
function participationRoom():void{requirev((int)one("SELECT COUNT(*) n FROM registrations WHERE status='active'")['n']<(int)setting()['capacity'],'参加定員に達しています。幹事へご相談ください。');}
function lifecycleStatus(array $u,array $p,string $next,string $action,string $reason):void{q('UPDATE registrations SET status=?,revision=revision+1 WHERE id=?',[$next,$p['id']]);logv((int)$u['id'],$action,'registration:'.$p['id'],['status'=>$p['status'],'revision'=>$p['revision']],['status'=>$next,'revision'=>(int)$p['revision']+1,'original_amount'=>(int)$p['amount'],'refunded'=>refundedRegistration((int)$p['id'])],$reason);}
function withdrawCancellation(array $u,array $d):void{deadline('change');$reason=reasonv($d);$p=registrationFor((int)$u['id']);requirev($p&&$p['status']==='cancel_requested','欠席申請中の申込ではありません。');requirev((int)$p['revision']===(int)($d['revision']??0),'内容が更新されています。画面を読み直してください。');participationRoom();lifecycleStatus($u,$p,'active','欠席申請の取り消し',$reason);}
function requestRejoin(array $u,array $d):void{deadline('change');$reason=reasonv($d);$p=registrationFor((int)$u['id']);requirev($p&&$p['status']==='cancelled','取消確定済みの申込ではありません。');requirev((int)$p['revision']===(int)($d['revision']??0),'内容が更新されています。画面を読み直してください。');lifecycleStatus($u,$p,'rejoin_requested','再参加の希望',$reason);}
function decideRejoin(array $u,array $d):void{lifecycleStaff($u);$reason=reasonv($d);$p=one('SELECT * FROM registrations WHERE id=?',[(int)($d['id']??0)]);$decision=$d['decision']??'';requirev($p&&$p['status']==='rejoin_requested'&&in_array($decision,['approve','reject'],true),'再参加申請と判断を確認してください。');if($decision==='approve'){participationRoom();requirev(plannedRegistrationRefund((int)$p['id'])===0,'先に未送金の返金予定を取り消してください。');}lifecycleStatus($u,$p,$decision==='approve'?'active':'cancelled','再参加の判断',$reason);}
function decideCancellation(array $u,array $d):void{lifecycleStaff($u);$reason=reasonv($d);$p=one('SELECT * FROM registrations WHERE id=?',[(int)($d['id']??0)]);$decision=$d['decision']??'';requirev($p&&$p['status']==='cancel_requested'&&in_array($decision,['approve','reject'],true),'欠席申請と判断を確認してください。');if($decision==='reject')participationRoom();lifecycleStatus($u,$p,$decision==='approve'?'cancelled':'active','欠席申請判定',$reason);}
function planRegistrationRefund(array $u,array $d):int{global $db;lifecycleStaff($u);$reason=reasonv($d);$key=(string)($d['request_key']??'');requirev((bool)preg_match('/^[a-f0-9]{32}$/D',$key),'返金画面を読み直してください。');$old=one('SELECT id FROM refunds WHERE request_key=?',[$key]);if($old)return (int)$old['id'];$id=(int)($d['registration_id']??0);$p=one('SELECT * FROM registrations WHERE id=?',[$id]);requirev($p&&in_array($p['status'],['active','cancelled'],true),'欠席・再参加の判断後に返金を登録してください。');$n=moneyv($d['amount']??'');requirev($n>0&&$n<=availableRegistrationRefund($id),'返金可能額を超えています。重複予定も確認してください。');q('INSERT INTO refunds (registration_id,amount,status,refund_date,reference_text,request_key,actor_id,created,updated) VALUES (?,?,?,?,?,?,?,?,?)',[$id,$n,'planned','','',$key,$u['id'],nowv(),nowv()]);$rid=(int)$db->lastInsertId();logv((int)$u['id'],'返金予定の登録','registration:'.$id,null,['refund_id'=>$rid,'amount'=>$n,'status'=>'planned'],$reason);return $rid;}
function refundRecord(int $id):array{$x=one('SELECT * FROM refunds WHERE id=?',[$id]);requirev((bool)$x,'返金記録がありません。');return $x;}
function paidRefund(int $id):int{return (int)one('SELECT COALESCE(SUM(amount),0) n FROM refund_links WHERE refund_id=? AND active=1',[$id])['n'];}
function recordRegistrationRefund(array $u,array $d):void{lifecycleStaff($u);$reason=reasonv($d);$x=refundRecord((int)($d['id']??0));$p=one('SELECT * FROM registrations WHERE id=?',[$x['registration_id']]);requirev($x['status']==='planned'&&in_array($p['status'],['active','cancelled'],true),'申請状態と未送金の返金予定を確認してください。');$date=datev((string)($d['date']??''));requirev($date<=date('Y-m-d'),'返金日は今日以前にしてください。');$reference=trim((string)($d['reference']??''));requirev($reference!==''&&mb_strlen($reference)<=200,'送金確認番号などを200文字以内で入力してください。口座番号は不要です。');$id=(int)$p['id'];requirev(refundedRegistration($id)+plannedRegistrationRefund($id)<=max(0,paidRegistration($id)-billedRegistration($p)),'返金可能額を再確認してください。');q("UPDATE refunds SET status='recorded',refund_date=?,reference_text=?,updated=? WHERE id=?",[$date,$reference,nowv(),$x['id']]);logv((int)$u['id'],'返金実施の記録（送金なし）','registration:'.$id,$x,refundRecord((int)$x['id']),$reason);}
function cancelRegistrationRefund(array $u,array $d):void{lifecycleStaff($u);$reason=reasonv($d);$x=refundRecord((int)($d['id']??0));requirev($x['status']==='planned','未送金の返金予定だけ取り消せます。');q("UPDATE refunds SET status='cancelled',updated=? WHERE id=?",[nowv(),$x['id']]);logv((int)$u['id'],'返金予定の取り消し','registration:'.$x['registration_id'],$x,refundRecord((int)$x['id']),$reason);}
function undoRegistrationRefund(array $u,array $d):void{lifecycleStaff($u);$reason=reasonv($d);$x=refundRecord((int)($d['id']??0));requirev($x['status']==='recorded'&&paidRefund((int)$x['id'])===0,'先に銀行出金との照合を取り消してください。');q("UPDATE refunds SET status='planned',refund_date='',reference_text='',updated=? WHERE id=?",[nowv(),$x['id']]);logv((int)$u['id'],'返金記録の訂正（実送金の取消ではありません）','registration:'.$x['registration_id'],$x,refundRecord((int)$x['id']),$reason);}
function linkRegistrationRefund(array $u,array $d):void{global $db;lifecycleStaff($u);$reason=reasonv($d);$x=refundRecord((int)($d['id']??0));$t=one('SELECT * FROM bank_transactions WHERE id=?',[(int)($d['bank_id']??0)]);$n=moneyv($d['amount']??'');requirev($x['status']==='recorded'&&$t&&$t['state']==='confirmed'&&(int)$t['debit']>0,'返金記録と確認済み銀行出金を選んでください。');requirev($n>0&&$n<=(int)$x['amount']-paidRefund((int)$x['id'])&&$n<=(int)$t['debit']-usedBank((int)$t['id']),'返金または出金の未照合額を超えています。');q('INSERT INTO refund_links (refund_id,bank_id,amount,active,reason,actor_id,created) VALUES (?,?,?,?,?,?,?)',[$x['id'],$t['id'],$n,1,$reason,$u['id'],nowv()]);logv((int)$u['id'],'返金と銀行出金の照合','registration:'.$x['registration_id'],null,['refund_id'=>$x['id'],'bank_id'=>$t['id'],'amount'=>$n,'link_id'=>(int)$db->lastInsertId()],$reason);}
function unlinkRegistrationRefund(array $u,array $d):void{lifecycleStaff($u);$reason=reasonv($d);$a=one('SELECT * FROM refund_links WHERE id=?',[(int)($d['id']??0)]);requirev($a&&(int)$a['active']===1,'有効な返金照合ではありません。');q('UPDATE refund_links SET active=0 WHERE id=?',[$a['id']]);logv((int)$u['id'],'返金出金照合の取り消し','refund:'.$a['refund_id'],$a,['active'=>0],$reason);}
